import type { Stop, Tour } from "./types";
import { umea } from "./umea";

// German variant of the Umeå tour. Positions and stop order come from ./umea;
// the MP3s use the same file names as the English ones, in a "de" subfolder, and are
// generated by scripts/generate-umea-audio.mjs.
const AUDIO_BASE = "/audio/Umea/de";

const audioFile = (path: string) => `${AUDIO_BASE}/${path.split("/").pop()}`;

const stopTexts: Record<string, Pick<Stop, "name" | "walkHint">> = {
  poi_1: { name: "Broparken", walkHint: "~3 Min. zu Fuß zum Kulturväven" },
  walk_1: { name: "Weg zum Kulturväven" },
  poi_2: { name: "Kulturväven (Väven)", walkHint: "~1 Min. zu Fuß zum Stora Hotellet" },
  walk_2: { name: "Weg zum Stora Hotellet" },
  poi_3: { name: "Stora Hotellet", walkHint: "~2 Min. zu Fuß zum Rådhustorget" },
  walk_3: { name: "Weg zum Rådhustorget" },
  poi_4: { name: "Rådhustorget", walkHint: "~3 Min. zu Fuß zur Umeå Stadskyrka" },
  walk_4: { name: "Weg zur Umeå Stadskyrka" },
  poi_5: { name: "Umeå Stadskyrka", walkHint: "~2 Min. zu Fuß zum Twintowns Park" },
  walk_5: { name: "Weg zum Twintowns Park" },
  poi_6: { name: "Twintowns Park", walkHint: "~5 Min. zu Fuß zum Bildmuseet" },
  walk_6: { name: "Weg zum Bildmuseet" },
  poi_7: { name: "Bildmuseet" },
};

export const umeaDe: Tour = {
  ...umea,
  title: "Umeå Stadtführung",
  shortTitle: "Umeå Stadtführung",
  region: "Västerbotten, Schweden",
  description:
    "Entdecke die Flussstadt Umeå mit deiner persönlichen Audioführung — 7 ausgewählte Stopps entlang des Ume älv, vom Broparken bis zum Bildmuseet.",
  duration: "~1,5 Stunden",
  language: { code: "de", label: "Deutsch", flag: "🇩🇪" },
  intro: { label: "Willkommen in Umeå", audio: umea.intro.audio.map(audioFile) },
  guide: { ...umea.guide, introAudio: audioFile(umea.guide.introAudio) },
  completeText: "Du hast das Herz von Umeå entdeckt",
  shareText: "Ich habe gerade Umeå mit meinem persönlichen KI-Stadtführer entdeckt. 🎧🗺️",
  stops: umea.stops.map((stop) => ({
    ...stop,
    ...stopTexts[stop.id],
    audio: stop.audio.map(audioFile),
  })),
};
